#ifndef MATERIAL_TARGET_GLUING_H
#define MATERIAL_TARGET_GLUING_H
#include "material_target_analytic.h"
namespace material_target_gluing {
namespace ti=material_target_inverse;namespace tg=material_target_general;namespace ta=material_target_analytic;namespace mf=material_forward;
using Q=ti::Q;using S=ti::S;using R=long double;
static Q norm2(S x,S y){return ti::mag(mf::root(S(ti::mag(x))*S(ti::mag(x))+S(ti::mag(y))*S(ti::mag(y))));}
static Q lipschitz(const tg::Map&m,const curved::Record&r){S box[2];for(int k=0;k<2;k++){Q lo=Q(r.triangle.geometry.x[0][k]),hi=lo;for(int a=1;a<3;a++){lo=std::min(lo,Q(r.triangle.geometry.x[a][k]));hi=std::max(hi,Q(r.triangle.geometry.x[a][k]));}S center=(S(lo)+S(hi))/S(2),half=(S(hi)-S(lo))/S(2);box[k]=S(center.n,ti::add(center.e,ti::mag(half)));}auto p=tg::evaluate<Q>(m,box[0],box[1]);Q L=0;for(int i=0;i<2;i++){Q row=0;for(int j=0;j<2;j++)row=ti::add(row,ti::mag(p.F[2*i+j]-S(i==j?1:0)));L=std::max(L,row);}return L;}
struct Trace {S p[2][4],v[2][4],B[2][2],V[2][2];};
static Trace trace_difference(const tg::Map&a,const tg::Map&b,const S*D){Trace out;for(int k=0;k<2;k++){for(int i=0;i<=3;i++)for(int j=0;i+j<=3;j++){S monomial(1);for(int q=0;q<i;q++)monomial=monomial*D[0];for(int q=0;q<j;q++)monomial=monomial*D[1];out.p[k][i+j]=out.p[k][i+j]+(a.x[k].c[i][j]-b.x[k].c[i][j])*monomial;out.v[k][i+j]=out.v[k][i+j]+(a.v[k].c[i][j]-b.v[k].c[i][j])*monomial;}for(int j=0;j<2;j++){out.B[k][j]=a.Bx[k][j]-b.Bx[k][j];out.V[k][j]=a.Bv[k][j]-b.Bv[k][j];}}return out;}
static S value(const S*c,S t){S z=c[3];for(int i=2;i>=0;i--)z=z*t+c[i];return z;}
struct Result {bool pass=true;const char*reason="pass";Q error[24][12]={},max_position=0,max_velocity=0;uint64_t paired=0,parts=0,possible_target_parts=0;};
static Result audit(const curved::Packet&p,size_t selected,const std::vector<curved_partition::Site>&sites,const std::vector<R>&weights,const std::string&dest){
    std::map<Key,std::vector<Edge>> edges;for(size_t it=0;it<p.record.size();it++)for(int a=0;a<3;a++){Pt x={p.record[it].triangle.geometry.x[a][0],p.record[it].triangle.geometry.x[a][1]},y={p.record[it].triangle.geometry.x[(a+1)%3][0],p.record[it].triangle.geometry.x[(a+1)%3][1]};edges[x<y?Key(x,y):Key(y,x)].push_back({it,p.record[it].component,x,y});}
    std::ofstream ledger(dest+"/shared_trace_strip_parts.csv"),receiver(dest+"/shared_trace_receiver_bounds.csv");ledger<<"left,right,part,position_gap_bound,velocity_gap_bound,strip_area_bound,left_L,right_L,extension_local_L,extension_limit,field_envelope_complete\n";receiver<<"left,right,part,target,moment,domain_and_field_ambiguity_bound\n";Result out;
    for(auto&entry:edges){bool touches=false;for(auto&e:entry.second)touches=touches||e.triangle==selected;if(!touches)continue;if(entry.second.size()!=2){out.pass=false;out.reason="unpaired_selected_material_edge";continue;}out.paired++;const auto&left=p.record[entry.second[0].triangle];const auto&right=p.record[entry.second[1].triangle];S A[2]={S(Q(entry.first.first[0])),S(Q(entry.first.first[1]))},D[2]={S(Q(entry.first.second[0]))-A[0],S(Q(entry.first.second[1]))-A[1]};Q anchor[2]={(A[0]+D[0]/S(2)).n,(A[1]+D[1]/S(2)).n};auto ml=tg::compile(left,anchor,p.parameters[3]),mr=tg::compile(right,anchor,p.parameters[3]);auto trace=trace_difference(ml,mr,D);Q Ll=lipschitz(ml,left),Lr=lipschitz(mr,right);if(Ll>=1||Lr>=1){out.pass=false;out.reason="shared_source_not_injective";continue;}Q origin[2]={tg::evaluate<Q>(ml,S(anchor[0]),S(anchor[1])).position[0].n,tg::evaluate<Q>(ml,S(anchor[0]),S(anchor[1])).position[1].n};
        for(int part=0;part<16;part++){Q midpoint=(Q(part)+Q(.5L))/16-Q(.5L),radius=Q(1)/32;S t(midpoint,radius),X=S(anchor[0])+D[0]*t,Y=S(anchor[1])+D[1]*t,z=X*X+Y*Y+S(Q(p.parameters[3]))*S(Q(p.parameters[3])),omega=mf::power(z,Q(-.75L)),initial[2]={-Y*omega,X*omega};S gap[2],vgap[2];for(int k=0;k<2;k++){gap[k]=value(trace.p[k],t);vgap[k]=value(trace.v[k],t);for(int a=0;a<2;a++){gap[k]=gap[k]+trace.B[k][a]*initial[a];vgap[k]=vgap[k]+trace.V[k][a]*initial[a];}}Q dx=norm2(gap[0],gap[1]),dv=norm2(vgap[0],vgap[1]);out.max_position=std::max(out.max_position,dx);out.max_velocity=std::max(out.max_velocity,dv);auto ql=tg::evaluate<Q>(ml,X,Y),qr=tg::evaluate<Q>(mr,X,Y);S tangent_l[2],tangent_r[2];for(int k=0;k<2;k++){tangent_l[k]=ql.F[2*k]*D[0]+ql.F[2*k+1]*D[1];tangent_r[k]=qr.F[2*k]*D[0]+qr.F[2*k+1]*D[1];}Q L=ti::mag((S(norm2(tangent_l[0],tangent_l[1]))+S(norm2(tangent_r[0],tangent_r[1])))/S(2));Q area=ti::add(ti::mul(ti::mul(dx,L),Q(1)/16),ti::mul(Q(8),ti::mul(dx,dx))),pad=ta::quotient_up(ti::mul(Q(2),dx),ta::difference_down(1,std::max(Ll,Lr)));Q local[2]={X.n,Y.n},rr[2];for(int k=0;k<2;k++)rr[k]=ti::add(k?Y.e:X.e,pad);auto bl=ta::bounds(tg::compile(left,local,p.parameters[3]),p,rr),br=ta::bounds(tg::compile(right,local,p.parameters[3]),p,rr);auto fl=tg::evaluate<Q>(ml,S(local[0],rr[0]),S(local[1],rr[1]));auto fr=tg::evaluate<Q>(mr,S(local[0],rr[0]),S(local[1],rr[1]));Q local_L=0;for(int i=0;i<2;i++){Q rl=0,rr_=0;for(int j=0;j<2;j++){rl=ti::add(rl,ti::mag(fl.F[2*i+j]-S(i==j?1:0)));rr_=ti::add(rr_,ti::mag(fr.F[2*i+j]-S(i==j?1:0)));}local_L=std::max({local_L,rl,rr_});}Q extension_limit=ti::lower((S(1)+S(std::max(Ll,Lr)))/S(2));bool fields=bl.pass&&br.pass&&local_L<extension_limit;ledger<<entry.second[0].triangle<<','<<entry.second[1].triangle<<','<<part<<','<<qs(dx)<<','<<qs(dv)<<','<<qs(area)<<','<<qs(Ll)<<','<<qs(Lr)<<','<<qs(local_L)<<','<<qs(extension_limit)<<','<<fields<<'\n';out.parts++;if(!fields){out.pass=false;out.reason="shared_trace_field_envelope";continue;}
            S physical[2];for(int k=0;k<2;k++){Q lo=std::min(ti::lower(ql.position[k]),ti::lower(qr.position[k])),hi=std::max(ti::upper(ql.position[k]),ti::upper(qr.position[k]));S center=(S(lo)+S(hi))/S(2),half=(S(hi)-S(lo))/S(2);physical[k]=S(center.n,ti::add(center.e,ti::add(ti::mag(half),dx)));}for(int target=0;target<int(sites.size());target++){bool possible=true;for(int j=0;j<int(sites.size());j++)if(j!=target){auto plane=tg::plane(sites,weights,target,j,origin);if(ti::lower(tg::value(plane,physical[0],physical[1],origin))>0){possible=false;break;}}if(!possible)continue;out.possible_target_parts++;for(int k=0;k<12;k++){Q error=ti::mul(area,ti::add(bl.moment[k],br.moment[k]));out.error[target][k]=ti::add(out.error[target][k],error);receiver<<entry.second[0].triangle<<','<<entry.second[1].triangle<<','<<part<<','<<sites[target].id<<','<<moment_names[k]<<','<<qs(error)<<'\n';}}}
    }ledger.close();receiver.close();return out;
}
}
#endif
